import{_ as a,o as e,c as l,a4 as o}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"廖建军 AI 人格模拟项目 — 设计与架构文档","description":"","frontmatter":{"title":"廖建军 AI 人格模拟项目 — 设计与架构文档","date":"2026-07-04T00:00:00.000Z"},"headers":[],"relativePath":"posts/qwen-agent-design.md","filePath":"posts/qwen-agent-design.md"}'),r={name:"posts/qwen-agent-design.md"};function d(i,t,n,h,s,u){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="廖建军-ai-人格模拟项目-—-设计与架构文档" tabindex="-1">廖建军 AI 人格模拟项目 — 设计与架构文档 <a class="header-anchor" href="#廖建军-ai-人格模拟项目-—-设计与架构文档" aria-label="Permalink to &quot;廖建军 AI 人格模拟项目 — 设计与架构文档&quot;">​</a></h1><h2 id="_1-项目目标" tabindex="-1">1. 项目目标 <a class="header-anchor" href="#_1-项目目标" aria-label="Permalink to &quot;1. 项目目标&quot;">​</a></h2><p>用一个 <strong>0.5B 参数的小模型</strong>，在 <strong>AMD RX 590 GME（8GB VRAM）</strong> 上运行，通过 <strong>QLoRA + Agent + RAG</strong> 三层架构，模拟微信好友&quot;廖建军&quot;的聊天风格（口癖、话题偏好、情绪反应），实现自然对话。</p><p><strong>最终形态</strong>：一个本地的 Agent 服务，接收用户消息，判断是否需要调用工具，需要时用基础模型（无LoRA），需要回话时用 LoRA 模型输出对方风格回复。</p><h2 id="_2-硬件与软件约束" tabindex="-1">2. 硬件与软件约束 <a class="header-anchor" href="#_2-硬件与软件约束" aria-label="Permalink to &quot;2. 硬件与软件约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规格</th></tr></thead><tbody><tr><td>GPU</td><td>AMD RX 590 GME (Polaris/GCN4, 8GB VRAM)</td></tr><tr><td>系统内存</td><td>16GB</td></tr><tr><td>操作系统</td><td>Windows</td></tr><tr><td>编译器</td><td>MSVC 19.44 (VS BuildTools) + CMake</td></tr><tr><td>GPU 加速</td><td>Vulkan SDK 1.4.350.0</td></tr><tr><td>不支持</td><td>ROCm, CUDA, Tensor Cores, DirectML</td></tr></tbody></table><p><strong>关键制约</strong>：</p><ul><li>没有 Tensor Cores → 训练极慢（但 0.5B 参数可接受）</li><li>无 ROCm → 只能用 Vulkan 后端</li><li>Vulkan 后端在 Windows 下需要控制台窗口才能初始化</li></ul><h2 id="_3-技术栈现状" tabindex="-1">3. 技术栈现状 <a class="header-anchor" href="#_3-技术栈现状" aria-label="Permalink to &quot;3. 技术栈现状&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>状态</th><th>路径</th></tr></thead><tbody><tr><td>基础模型</td><td>✅ Qwen2.5-0.5B-Instruct Q4_K_M GGUF (480MB)</td><td>models/qwen2.5-0.5b-instruct-q4_k_m.gguf</td></tr><tr><td>QLoRA 训练工具</td><td>✅ PR #22705 编译成功</td><td>bin/llama-finetune-qlora.exe (Vulkan)</td></tr><tr><td>LLM 推理工具</td><td>✅ 同一 PR 编译</td><td>bin/llama-cli.exe (Vulkan)</td></tr><tr><td>HTTP 服务器</td><td>✅ 每次请求加载模型（3-5s）</td><td>scripts/api_server.py</td></tr><tr><td>持久化服务器</td><td>❌ 尝试失败（stdin pipe 在 Windows 不可靠）</td><td>待用 llama-server.exe</td></tr><tr><td>Agent 层</td><td>❌ 未实现</td><td>设计目标</td></tr><tr><td>RAG 层</td><td>❌ 未实现</td><td>远期目标</td></tr></tbody></table><h2 id="_4-数据情况" tabindex="-1">4. 数据情况 <a class="header-anchor" href="#_4-数据情况" aria-label="Permalink to &quot;4. 数据情况&quot;">​</a></h2><h3 id="_4-1-数据来源" tabindex="-1">4.1 数据来源 <a class="header-anchor" href="#_4-1-数据来源" aria-label="Permalink to &quot;4.1 数据来源&quot;">​</a></h3><p><strong>全部为私聊记录，非群聊</strong>。</p><table tabindex="0"><thead><tr><th>来源</th><th>文件</th><th>条数</th><th>时间范围</th></tr></thead><tbody><tr><td>微信</td><td>liao_wxid_ibhm6rb434r522.jsonl</td><td>357,548</td><td>2022-11 ~ 2026-07</td></tr><tr><td>QQ</td><td>qq_1026044893_final.jsonl</td><td>379,300</td><td>2022-10 ~ 2025-12</td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>736,848</strong></td><td>2022-10 ~ 2026-07</td></tr></tbody></table><h3 id="_4-2-微信格式" tabindex="-1">4.2 微信格式 <a class="header-anchor" href="#_4-2-微信格式" aria-label="Permalink to &quot;4.2 微信格式&quot;">​</a></h3><p><code>json {&quot;db&quot;:0,&quot;type&quot;:1,&quot;isSender&quot;:1,&quot;createTime&quot;:1667729933, &quot;datetime&quot;:&quot;2022-11-06 18:18:53&quot;, &quot;content&quot;:&quot;怎么你把大伙们沉默了啊&quot;} </code></p><ul><li>isSender=1 = 你（wxid_gbxd54iv2sn422）</li><li>isSender=0 = 廖建军（wxid_ibhm6rb434r522）</li><li>type=1=文本, type=3=图片(XML)</li></ul><p>已存在清洗版：liao_..._clean.jsonl，归一化为 sender 字段格式。</p><h3 id="_4-3-qq-格式" tabindex="-1">4.3 QQ 格式 <a class="header-anchor" href="#_4-3-qq-格式" aria-label="Permalink to &quot;4.3 QQ 格式&quot;">​</a></h3><p><code>json {&quot;time&quot;:&quot;2022-10-04 11:48:00&quot;,&quot;sender&quot;:2036680567,&quot;type&quot;:&quot;text&quot;,&quot;text&quot;:&quot;怎么办啊&quot;} </code></p><ul><li>sender=2036680567 = 你</li><li>sender=1026044893 = 廖建军</li></ul><h3 id="_4-4-廖建军说话特征-样本分析" tabindex="-1">4.4 廖建军说话特征（样本分析） <a class="header-anchor" href="#_4-4-廖建军说话特征-样本分析" aria-label="Permalink to &quot;4.4 廖建军说话特征（样本分析）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>值</th></tr></thead><tbody><tr><td>平均消息长度</td><td>6.5 字</td></tr><tr><td>&lt;=2字短消息比例</td><td>~10%（&quot;确实&quot;&quot;爬&quot;&quot;爽&quot;&quot;啊这&quot;）</td></tr><tr><td>风格</td><td>口语化、直接、带攻击性</td></tr><tr><td>高频词</td><td>&quot;吼吼&quot;（笑声）、&quot;坏了&quot;、&quot;逆天&quot;、&quot;纯纯&quot;</td></tr><tr><td>常见句式</td><td>&quot;不是...吗&quot;反问、&quot;我&quot;开头表达观点</td></tr><tr><td>话题</td><td>游戏(LOL/原神/魔兽)、政治(特朗普/哈里斯)、社会、科技(马斯克)、日常吐槽</td></tr><tr><td>网络用语</td><td>&quot;一般货色&quot;&quot;差不多得了&quot;&quot;纯纯fw&quot;&quot;爬睡了&quot;</td></tr></tbody></table><h2 id="_5-已完成的实验" tabindex="-1">5. 已完成的实验 <a class="header-anchor" href="#_5-已完成的实验" aria-label="Permalink to &quot;5. 已完成的实验&quot;">​</a></h2><h3 id="_5-1-qlora-训练验证" tabindex="-1">5.1 QLoRA 训练验证 <a class="header-anchor" href="#_5-1-qlora-训练验证" aria-label="Permalink to &quot;5.1 QLoRA 训练验证&quot;">​</a></h3><ul><li>训练工具：llama-finetune-qlora.exe（PR #22705，Vulkan 后端）</li><li>基础模型：Qwen2.5-0.5B-Instruct Q4_K_M GGUF</li><li>实验数据：8 条假样本（非真实数据）</li><li>LoRA 参数：rank=16, alpha=16, 120 个权重矩阵, 2.16M 参数</li><li>训练速度：~6s/epoch（10 样本，ctx=512）</li><li>结果：模型成功改变身份（输出&quot;我叫廖建军&quot;），但质量差</li></ul><p><strong>LoRA 零token问题</strong>：加载 LoRA 后模型输出 Generation: 1000000.0 t/s（生成0 token，直接吐 EOS）。可能原因：数据过少过拟合/LoRA GGUF 兼容性/GPU 状态不稳定。</p><h3 id="_5-2-api-服务器验证" tabindex="-1">5.2 API 服务器验证 <a class="header-anchor" href="#_5-2-api-服务器验证" aria-label="Permalink to &quot;5.2 API 服务器验证&quot;">​</a></h3><ul><li>Python http.server + subprocess.Popen，每次请求 -f 传文件</li><li>CREATE_NO_WINDOW 避免弹窗，响应时间 ~4-5s/请求</li><li>输出 OpenAI 兼容格式，已验证基础模型和工具调用正常</li></ul><h3 id="_5-3-持久化进程尝试-失败" tabindex="-1">5.3 持久化进程尝试（失败） <a class="header-anchor" href="#_5-3-持久化进程尝试-失败" aria-label="Permalink to &quot;5.3 持久化进程尝试（失败）&quot;">​</a></h3><ul><li>尝试 --interactive 模式持久运行，stdin/stdout pipe 通信</li><li>失败：Windows 下 cmd /c 不转发 stdin pipe 给子进程</li><li>结论：需要编译 llama-server.exe 实现持久化</li></ul><h2 id="_6-需要设计的架构" tabindex="-1">6. 需要设计的架构 <a class="header-anchor" href="#_6-需要设计的架构" aria-label="Permalink to &quot;6. 需要设计的架构&quot;">​</a></h2><h3 id="_6-1-核心问题" tabindex="-1">6.1 核心问题 <a class="header-anchor" href="#_6-1-核心问题" aria-label="Permalink to &quot;6.1 核心问题&quot;">​</a></h3><p><code>用户输入 → ? → 廖建军风格回复</code></p><ol><li>何时调用工具？判断逻辑在 Agent 层还是模型层？</li><li>LoRA 和工具调用如何共存？一次只加载一个模型，还是切换？</li><li>长回复拆条？廖建军连发多条短消息，AI 输出一段话要不要拆？</li><li>上下文管理？保持最近 N 轮对话，防止爆上下文</li><li>RAG 是否必要？旧聊天记录做 memory augmentation？</li></ol><h3 id="_6-2-建议架构" tabindex="-1">6.2 建议架构 <a class="header-anchor" href="#_6-2-建议架构" aria-label="Permalink to &quot;6.2 建议架构&quot;">​</a></h3><p><code> ┌──────────┐ │ 用户输入 │ └────┬─────┘ │ ┌────▼─────┐ │ Agent │ │ 调度层 │ │ 1.上下文 │ │ 2.意图 │ │ 3.分发 │ └────┬─────┘ │ ┌──────────┼──────────┐ │ │ │ ┌─────▼─────┐ ┌──▼────┐ ┌──▼──────┐ │ 基础模型 │ │ LoRA │ │ RAG │ │ (无LoRA) │ │ (风格) │ │ (FAISS) │ │ 工具调用 │ │ 回复 │ │ 历史记忆│ └───────────┘ └───────┘ └─────────┘</code></p><p><strong>关键决策</strong>：</p><p>A. LoRA 与工具调用分离：工具调用走基础模型（无 LoRA），风格回复走 LoRA 模型</p><p>B. Agent 调度：先判断是否需要工具 → 需要则调基础模型 → 否则调 LoRA 模型</p><p>C. 长回复拆条：按句号/感叹号/换行切分，1-3条/次，间隔 0.5-1s</p><p>D. 上下文：最近 8-12 轮，~2K tokens 上限，超出丢弃最早的</p><h3 id="_6-3-持久化方案" tabindex="-1">6.3 持久化方案 <a class="header-anchor" href="#_6-3-持久化方案" aria-label="Permalink to &quot;6.3 持久化方案&quot;">​</a></h3><p>每次请求 3-5s 加载模型，不可用于实时对话。</p><p><strong>方案 1：编译 llama-server.exe</strong>（推荐）</p><ul><li>从 ggerganov/llama.cpp 主仓库编译，支持 --lora、常驻 VRAM、&lt;1s 延迟</li><li>编译方法与 llama-cli 相同（MSVC + Vulkan）</li></ul><p><strong>方案 2：双进程切换</strong> → 不行，VRAM 不够同时加载两个 0.5B</p><p><strong>方案 3：单进程动态重载</strong> → 每次重载仍需 3-5s，无意义</p><h3 id="_6-4-rag-设计-远期" tabindex="-1">6.4 RAG 设计（远期） <a class="header-anchor" href="#_6-4-rag-设计-远期" aria-label="Permalink to &quot;6.4 RAG 设计（远期）&quot;">​</a></h3><p>全量聊天记录(736K条) → bge-small-zh embedding → FAISS 索引 → 运行时检索相似场景插入上下文</p><h2 id="_7-需要设计的内容" tabindex="-1">7. 需要设计的内容 <a class="header-anchor" href="#_7-需要设计的内容" aria-label="Permalink to &quot;7. 需要设计的内容&quot;">​</a></h2><h3 id="_7-1-agent-层详细设计" tabindex="-1">7.1 Agent 层详细设计 <a class="header-anchor" href="#_7-1-agent-层详细设计" aria-label="Permalink to &quot;7.1 Agent 层详细设计&quot;">​</a></h3><ol><li>Python 框架选择：asyncio / FastAPI / Flask？是否需要 WebSocket 流式输出？</li><li>意图判断：规则匹配 vs 小模型分类？多步工具调用怎么处理？</li><li>LoRA/基础模型切换策略：单进程下如何实现？llama-server API 能否切换 LoRA？</li><li>上下文窗口管理：建议 ctx 大小？滑动窗口策略？是否需要 token 计数？</li><li>输出格式：OpenAI 兼容？SSE 流式？长回复拆条算法细节？</li></ol><h3 id="_7-2-数据清洗策略" tabindex="-1">7.2 数据清洗策略 <a class="header-anchor" href="#_7-2-数据清洗策略" aria-label="Permalink to &quot;7.2 数据清洗策略&quot;">​</a></h3><ol><li>736K 条 → 训练样本：滑窗大小？连续发言合并？是否保留短消息？预计样本量？</li><li>LoRA 训练参数：rank=8 vs 16？学习率？epoch？冻结某些层？</li><li>评估方案：如何量化&quot;像不像&quot;？需要验证集吗？</li></ol><h3 id="_7-3-rag-可行性评估" tabindex="-1">7.3 RAG 可行性评估 <a class="header-anchor" href="#_7-3-rag-可行性评估" aria-label="Permalink to &quot;7.3 RAG 可行性评估&quot;">​</a></h3><ol><li>LoRA 能否记住足够信息，还是必须 RAG？</li><li>bge-small-zh 在 RX 590 上的性能（Vulkan 支持）？</li></ol><h3 id="_7-4-优先级建议" tabindex="-1">7.4 优先级建议 <a class="header-anchor" href="#_7-4-优先级建议" aria-label="Permalink to &quot;7.4 优先级建议&quot;">​</a></h3><p>分阶段计划：</p><ul><li>Phase 1：最小可行产品（1-2天）</li><li>Phase 2：优化体验（3-5天）</li><li>Phase 3：RAG 与完善（1-2周）</li></ul><h2 id="_8-参考文件与命令" tabindex="-1">8. 参考文件与命令 <a class="header-anchor" href="#_8-参考文件与命令" aria-label="Permalink to &quot;8. 参考文件与命令&quot;">​</a></h2><h3 id="_8-1-文件路径" tabindex="-1">8.1 文件路径 <a class="header-anchor" href="#_8-1-文件路径" aria-label="Permalink to &quot;8.1 文件路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>路径</th></tr></thead><tbody><tr><td>微信原始数据</td><td>D:\\files\\qwen-chat\\chat_records\\liao_wxid_ibhm6rb434r522.jsonl</td></tr><tr><td>微信清洗数据</td><td>D:\\files\\qwen-chat\\chat_records\\liao_wxid_ibhm6rb434r522_clean.jsonl</td></tr><tr><td>QQ 数据</td><td>D:\\files\\qwen-chat\\chat_records\\qq_1026044893_final.jsonl</td></tr><tr><td>训练工具</td><td>D:\\files\\qwen-chat\\bin\\llama-finetune-qlora.exe</td></tr><tr><td>推理工具</td><td>D:\\files\\qwen-chat\\bin\\llama-cli.exe</td></tr><tr><td>基础模型</td><td>D:\\files\\qwen-chat\\models\\qwen2.5-0.5b-instruct-q4_k_m.gguf</td></tr><tr><td>旧 LoRA</td><td>D:\\files\\qwen-chat\\adapters\\adapter.gguf</td></tr><tr><td>API 服务器</td><td>D:\\files\\qwen-chat\\scripts\\api_server.py</td></tr><tr><td>提取文档</td><td>D:\\files\\qwen-chat\\chat_records\\docs\\checkpoint.md</td></tr></tbody></table><h3 id="_8-2-关键命令" tabindex="-1">8.2 关键命令 <a class="header-anchor" href="#_8-2-关键命令" aria-label="Permalink to &quot;8.2 关键命令&quot;">​</a></h3><p>`\bash</p><h1 id="qlora-训练" tabindex="-1">QLoRA 训练 <a class="header-anchor" href="#qlora-训练" aria-label="Permalink to &quot;QLoRA 训练&quot;">​</a></h1><p>llama-finetune-qlora.exe -m model.gguf -t data.jsonl --lora-out adapter.gguf --rank 8 --alpha 8 -ngl 99 -mg 1</p><h1 id="推理-带lora" tabindex="-1">推理（带LoRA） <a class="header-anchor" href="#推理-带lora" aria-label="Permalink to &quot;推理（带LoRA）&quot;">​</a></h1><p>llama-cli.exe -m model.gguf --lora adapter.gguf -ngl 99 -mg 1 -p &quot;你好&quot; -n 200</p><h1 id="编译-llama-server" tabindex="-1">编译 llama-server <a class="header-anchor" href="#编译-llama-server" aria-label="Permalink to &quot;编译 llama-server&quot;">​</a></h1><p>cmake -B build -G &quot;Visual Studio 17 2022&quot; -DCMAKE_BUILD_TYPE=Release -DLLAMA_VULKAN=ON cmake --build build --config Release --target llama-server `</p><h2 id="_9-未解决问题" tabindex="-1">9. 未解决问题 <a class="header-anchor" href="#_9-未解决问题" aria-label="Permalink to &quot;9. 未解决问题&quot;">​</a></h2><ol><li>LoRA 零token生成的根因</li><li>llama-server 是否支持运行时切换 LoRA</li><li>Vulkan 在 RX 590 上的最大 batch size 和 ctx 限制</li><li>Qwen2.5-0.5B 在低 token 数下的工具调用可靠性</li></ol>',73)])])}const b=a(r,[["render",d]]);export{c as __pageData,b as default};
